        'Rien. Il n\'y a pas de compte, et nous ne demandons jamais de nom ni d\'adresse e-mail. Pas de publicité, pas de statistiques, pas de rapports d\'incident. Nous n\'avons aucun serveur, et l\'application ne nous envoie rien.',
    'privacyStoredTitle': 'Ce qui est stocké sur cet appareil',
    'privacyStoredBody':
        'Votre matériel importé, votre historique d\'apprentissage (réponses, dates de révision, série, Koto Seeds) et vos réglages. Rien ne quitte l\'appareil. Vous pouvez tout supprimer depuis « Tout effacer et repartir » et l\'exporter depuis « Sauvegarde ». La désinstallation supprime le tout.',
    'privacyAiTitle': 'À propos des services d\'IA',
    'privacyAiBody':
        'Vous utilisez l\'assistant que vous avez déjà. L\'application se contente de copier une consigne et, si vous le demandez, d\'ouvrir cet assistant — elle ne dialogue jamais avec l\'un d\'eux. Ce que vous envoyez à l\'assistant relève de la politique de ce service : prudence avec le matériel confidentiel.',
    'privacyPermissionsTitle': 'Autorisations de l\'appareil',
    'privacyPermissionsBody':
        'L\'application ne demande aucune autorisation Android, pas même l\'accès à Internet. La lecture à voix haute utilise la synthèse vocale intégrée à votre appareil.',
