    'termsUseTitle': 'À propos de cette application',
    'termsUseBody':
        'KotoLang est une application personnelle d\'apprentissage de l\'anglais, fournie gratuitement. Il n\'y a ni compte ni paiement. L\'utiliser vaut acceptation de ces conditions.',
    'termsMaterialTitle': 'Le matériel d\'étude',
    'termsMaterialBody':
        'Votre matériel est ce que vous avez demandé à une IA puis importé. Son exactitude n\'est pas garantie. Vérifiez tout ce sur quoi vous comptez vous appuyer au travail ou dans un cadre formel plutôt que de l\'utiliser tel quel.',
    'termsAiTitle': 'Recours à un service d\'IA',
    'termsAiBody':
        'Tout assistant que vous utilisez l\'est en vertu de votre propre accord avec son fournisseur. Cette application n\'est pas partie à cet accord et n\'est responsable ni de ce qu\'un assistant répond, ni de sa disponibilité.',
    'termsDataTitle': 'Vos données',
