        'Tout est stocké sur cet appareil uniquement. Les données peuvent être perdues si l\'appareil tombe en panne, est perdu ou réinitialisé, ou si l\'application est supprimée. En garder une copie vous revient ; nous ne pouvons rien récupérer pour vous.',
