    'privacyCollectTitle': 'Was wir erheben',
    'privacyCollectBody':
        'Nichts. Es gibt kein Konto, und wir fragen nie nach Namen oder E-Mail-Adresse. Keine Werbung, keine Analyse, keine Absturzberichte. Wir betreiben keinen Server, und die App sendet uns nichts.',
    'privacyStoredTitle': 'Was auf diesem Gerät gespeichert wird',
    'privacyStoredBody':
        'Ihr importiertes Material, Ihr Lernverlauf (Antworten, Wiederholungstermine, Serie, Koto Seeds) und Ihre Einstellungen. Nichts davon verlässt das Gerät. Sie können alles unter „Löschen und neu anfangen“ entfernen und unter „Sicherung“ exportieren. Beim Deinstallieren wird alles gelöscht.',
    'privacyAiTitle': 'Zu den KI-Diensten',
    'privacyAiBody':
        'Sie benutzen den Assistenten, den Sie ohnehin haben. Die App kopiert nur eine Eingabe und öffnet auf Wunsch diesen Assistenten — sie spricht selbst nie mit einem. Was Sie an den Assistenten schicken, unterliegt dessen eigener Richtlinie; seien Sie also mit vertraulichem Material vorsichtig.',
    'privacyPermissionsTitle': 'Geräteberechtigungen',
    'privacyPermissionsBody':
        'Die App fordert überhaupt keine Android-Berechtigungen an, nicht einmal Internetzugriff. Das Vorlesen nutzt die Sprachausgabe Ihres Geräts.',
    'privacyContactTitle': 'Kontakt',
    'privacyContactBody': 'kmkororoforana@gmail.com',
    'termsTitle': 'Nutzungsbedingungen',
    'termsUseTitle': 'Über diese App',
    'termsUseBody':
        'KotoLang ist eine persönliche App zum Englischlernen und kostenlos. Es gibt kein Konto und nichts zu bezahlen. Wer sie nutzt, nimmt diese Bedingungen an.',
    'termsMaterialTitle': 'Das Lernmaterial',
    'termsMaterialBody':
        'Ihr Material ist das, worum Sie eine KI gebeten und was Sie dann importiert haben. Für die Richtigkeit wird nicht garantiert. Prüfen Sie alles, worauf Sie sich beruflich oder förmlich stützen wollen, statt es unverändert zu verwenden.',
    'termsAiTitle': 'Nutzung eines KI-Dienstes',
    'termsAiBody':
        'Jeder Assistent, den Sie verwenden, wird nach Ihrer eigenen Vereinbarung mit dessen Anbieter genutzt. Diese App ist nicht Partei dieser Vereinbarung und haftet weder für die Antworten eines Assistenten noch dafür, dass er weiter verfügbar bleibt.',
    'termsDataTitle': 'Ihre Daten',
    'termsDataBody':
        'Alles liegt ausschließlich auf diesem Gerät. Es kann verloren gehen, wenn das Gerät ausfällt, verloren geht oder zurückgesetzt wird oder wenn die App entfernt wird. Eine Kopie aufzubewahren ist Ihre Sache; wir können nichts wiederherstellen.',
    'termsWarrantyTitle': 'Keine Gewähr',
    'termsWarrantyBody':
        'Die App wird wie besehen bereitgestellt. Sie garantiert keinen bestimmten Lernerfolg, und soweit das Gesetz es zulässt, haften wir nicht für Schäden aus ihrer Nutzung.',
