    'privacyCollectTitle': 'हम क्या इकट्ठा करते हैं',
    'privacyCollectBody':
        'कुछ नहीं। कोई खाता नहीं है, और हम कभी नाम या ईमेल नहीं माँगते। न विज्ञापन, न आँकड़े, न क्रैश रिपोर्ट। हम कोई सर्वर नहीं चलाते, और ऐप से हमें कुछ भी नहीं भेजा जाता।',
    'privacyStoredTitle': 'इस डिवाइस पर क्या रखा जाता है',
    'privacyStoredBody':
        'आपकी आयात की हुई सामग्री, आपका सीखने का रिकॉर्ड (जवाब, दोहराव की तारीख़ें, लड़ी, Koto Seeds) और आपकी सेटिंग्स। इनमें से कुछ भी डिवाइस से बाहर नहीं जाता। आप इसे “मिटाकर नए सिरे से शुरू करें” से हटा सकते हैं और “बैकअप” से निर्यात कर सकते हैं। ऐप हटाने पर सब चला जाता है।',
    'privacyAiTitle': 'AI सेवाओं के बारे में',
    'privacyAiBody':
        'आप वही सहायक इस्तेमाल करते हैं जो आपके पास पहले से है। ऐप सिर्फ़ एक प्रॉम्प्ट कॉपी करता है और कहने पर उस सहायक को खोल देता है — वह ख़ुद कभी किसी से बात नहीं करता। जो आप सहायक को भेजते हैं वह उस सेवा की अपनी नीति के तहत आता है, इसलिए गोपनीय सामग्री के साथ सावधानी बरतिए।',
    'privacyPermissionsTitle': 'डिवाइस अनुमतियाँ',
    'privacyPermissionsBody':
        'यह ऐप कोई भी Android अनुमति नहीं माँगता, इंटरनेट तक भी नहीं। बोलकर पढ़ने के लिए आपके डिवाइस की अपनी टेक्स्ट-टू-स्पीच का उपयोग होता है।',
    'privacyContactTitle': 'संपर्क',
    'privacyContactBody': 'kmkororoforana@gmail.com',
    'termsTitle': 'उपयोग की शर्तें',
    'termsUseTitle': 'इस ऐप के बारे में',
    'termsUseBody':
        'KotoLang अंग्रेज़ी सीखने का एक निजी ऐप है, जो मुफ़्त दिया जाता है। न कोई खाता है, न कुछ चुकाना है। इसे इस्तेमाल करने का अर्थ है इन शर्तों को मानना।',
    'termsMaterialTitle': 'पढ़ाई की सामग्री',
    'termsMaterialBody':
        'आपकी सामग्री वही है जो आपने किसी AI से लिखवाकर आयात की। इसकी सटीकता की कोई गारंटी नहीं है। काम में या औपचारिक जगह पर जिस पर भरोसा करना हो, उसे ज्यों का त्यों इस्तेमाल करने के बजाय जाँच लीजिए।',
    'termsAiTitle': 'AI सेवा का उपयोग',
    'termsAiBody':
        'आप जो भी सहायक इस्तेमाल करते हैं, वह उसके प्रदाता के साथ आपके अपने अनुबंध के तहत होता है। यह ऐप उस अनुबंध का पक्ष नहीं है और न सहायक के जवाब के लिए ज़िम्मेदार है, न इसके लिए कि वह उपलब्ध रहेगा या नहीं।',
    'termsDataTitle': 'आपका डेटा',
    'termsDataBody':
        'सब कुछ केवल इसी डिवाइस पर रखा जाता है। डिवाइस ख़राब होने, खो जाने, रीसेट होने या ऐप हटाने पर यह खो सकता है। प्रति रखना आपके ज़िम्मे है; हम आपके लिए कुछ भी वापस नहीं ला सकते।',
    'termsWarrantyTitle': 'कोई गारंटी नहीं',
    'termsWarrantyBody':
        'ऐप जैसा है वैसा दिया जाता है। यह किसी ख़ास सीखने के नतीजे की गारंटी नहीं देता, और क़ानून जहाँ तक अनुमति दे, इसके उपयोग से हुए नुक़सान के लिए हम ज़िम्मेदार नहीं हैं।',
