    'privacyCollectTitle': 'Apa yang kami kumpulkan',
    'privacyCollectBody':
        'Tidak ada. Tidak ada akun, dan kami tidak pernah meminta nama atau alamat email. Tidak ada iklan, tidak ada analitik, tidak ada laporan kerusakan. Kami tidak menjalankan server, dan aplikasi tidak mengirim apa pun kepada kami.',
    'privacyStoredTitle': 'Apa yang tersimpan di perangkat ini',
    'privacyStoredBody':
        'Materi yang Anda impor, catatan belajar Anda (jawaban, tanggal ulangan, rentetan, Koto Seeds) dan pengaturan Anda. Tidak ada yang keluar dari perangkat. Anda bisa menghapusnya lewat “Hapus dan mulai lagi” dan mengekspornya lewat “Cadangan”. Menghapus aplikasi menghilangkan semuanya.',
    'privacyAiTitle': 'Tentang layanan AI',
    'privacyAiBody':
        'Anda memakai asisten yang sudah Anda punya. Aplikasi hanya menyalin prompt dan, jika Anda minta, membuka asisten itu — ia tidak pernah berbicara sendiri dengan asisten mana pun. Apa pun yang Anda kirim ke asisten tunduk pada kebijakan layanan tersebut, jadi berhati-hatilah dengan materi rahasia.',
    'privacyPermissionsTitle': 'Izin perangkat',
    'privacyPermissionsBody':
        'Aplikasi ini tidak meminta izin Android apa pun, bahkan akses internet sekalipun. Pembacaan suara memakai text-to-speech bawaan perangkat Anda.',
    'privacyContactTitle': 'Kontak',
    'privacyContactBody': 'kmkororoforana@gmail.com',
    'termsTitle': 'Ketentuan penggunaan',
    'termsUseTitle': 'Tentang aplikasi ini',
    'termsUseBody':
        'KotoLang adalah aplikasi belajar bahasa Inggris untuk pemakaian pribadi, diberikan gratis. Tidak ada akun dan tidak ada yang perlu dibayar. Menggunakannya berarti menerima ketentuan ini.',
    'termsMaterialTitle': 'Materi belajar',
    'termsMaterialBody':
        'Materi Anda adalah apa yang Anda minta dari sebuah AI lalu Anda impor. Ketepatannya tidak dijamin. Periksa dulu apa pun yang hendak Anda andalkan di tempat kerja atau situasi resmi, jangan dipakai apa adanya.',
    'termsAiTitle': 'Memakai layanan AI',
    'termsAiBody':
        'Asisten apa pun yang Anda pakai, dipakai berdasarkan perjanjian Anda sendiri dengan penyedianya. Aplikasi ini bukan pihak dalam perjanjian itu dan tidak bertanggung jawab atas jawaban asisten maupun atas tersedianya layanan itu.',
    'termsDataTitle': 'Data Anda',
    'termsDataBody':
        'Semuanya tersimpan hanya di perangkat ini. Data bisa hilang jika perangkat rusak, hilang, disetel ulang, atau aplikasinya dihapus. Menyimpan salinan adalah urusan Anda; kami tidak dapat memulihkan apa pun.',
    'termsWarrantyTitle': 'Tanpa jaminan',
    'termsWarrantyBody':
        'Aplikasi diberikan apa adanya. Ia tidak menjamin hasil belajar tertentu dan, sejauh diizinkan hukum, kami tidak bertanggung jawab atas kerugian yang timbul dari penggunaannya.',
